mapper.sql:
AND snapshot_id=(
    SELECT current_snapshot_id FROM repositories WHERE id=#{repositoryId}
)

mapper.update:
UPDATE code_chunks SET snapshot_id=#{snapshotId},commit_sha=#{commitSha}
        WHERE repo_id=#{repositoryId}
        AND file_path NOT IN
            #{path}

mapper.select:
SELECT
FROM code_chunks WHERE repo_id=#{repositoryId}
ORDER BY CASE WHEN POSITION(LOWER(#{query}) IN LOWER(file_path))>0 THEN 4 ELSE 0 END+CASE WHEN POSITION(LOWER(#{query}) IN LOWER(COALESCE(symbol_name,'')))>0 THEN 3 ELSE 0 END+CASE WHEN POSITION(LOWER(#{query}) IN LOWER(COALESCE(symbol_kind,'')))>0 THEN 2 ELSE 0 END+CASE WHEN POSITION(LOWER(#{query}) IN LOWER(COALESCE(language,'')))>0 THEN 2 ELSE 0 END+CASE WHEN POSITION(LOWER(#{query}) IN LOWER(content))>0 THEN 1 ELSE 0 END DESC,file_path,start_line,id LIMIT #{limit} OFFSET #{offset}
